// EDIT THESE VALUES ONCE, then activate the workflow
return [{ json: {
  "twilioNumber": "YOUR_TWILIO_NUMBER",
  "sheetId": "PASTE_SHEET_ID",
  "business": "Your Business",
  "reviewLink": "https://g.page/r/YOUR_REVIEW_LINK",
  "hoursAfterJob": 2,
  "reminderAfterDays": 3,
  "fromName": "Your Name"
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const out = [];
for (const it of $input.all()) {
  const r = it.json; if (String(r['Status']).toLowerCase() !== 'done' || !r['Email']) continue;
  const done = parse(r['Completed']); if (!done) continue;
  const first = (String(r['Customer']||'').split(' ')[0]) || 'there';
  if (!r['Review sent']) {
    if ((Date.now() - done) / 36e5 < C.hoursAfterJob) continue;
    out.push({ json: { row_number: r.row_number, stage: 'Review sent', email: r['Email'], phone: r['Phone'] || '',
      subject: `Thanks from ${C.business} - quick favor?`,
      body: `Hi ${first},\n\nThank you for choosing ${C.business}. If you were happy with the work, would you leave us a quick Google review? It takes 30 seconds and means a lot to a local business:\n${C.reviewLink}\n\nThank you!\n${C.fromName}`,
      sms: `Hi ${first}, thanks for choosing ${C.business}! Would you leave us a quick review? ${C.reviewLink}` } });
  } else if (!r['Reminder sent'] && days(parse(r['Review sent']) || done, today) >= C.reminderAfterDays) {
    out.push({ json: { row_number: r.row_number, stage: 'Reminder sent', email: r['Email'], phone: r['Phone'] || '',
      subject: `Still have 30 seconds, ${first}?`,
      body: `Hi ${first},\n\nJust a friendly reminder - if you have a moment, a short review really helps us:\n${C.reviewLink}\n\nThanks again,\n${C.fromName}`,
      sms: `Friendly reminder from ${C.business}: ${C.reviewLink}` } });
  }
}
return out;
